-- ============================================================
--  Campeonatos Nacionales de IGP del CEPPB 2021-2025
--  5 campeonatos · 197 participaciones
--
--  Actas oficiales del club, extraídas de working-dog. Entran
--  ya validadas: las publica el club, no un particular.
--  Se puede ejecutar más de una vez sin duplicar nada.
-- ============================================================

begin;

-- 0. Columnas nuevas del acta: puntos, guía, año y la
--    calificación tal cual venía escrita en el original.
alter table resultados add column if not exists puntos integer;
alter table resultados add column if not exists guia text;
alter table resultados add column if not exists anio integer;
alter table resultados add column if not exists calificacion_origen text;

-- 1. Los campeonatos

-- 2. Las participaciones.
--    El trigger obliga a que todo resultado nazca sin validar y
--    sólo lo levante la junta desde la plataforma. Aquí es la
--    junta quien vuelca sus propias actas, así que se aparta un
--    momento y se vuelve a poner al terminar.
alter table resultados disable trigger trg_proteger_resultado;

on conflict (id) do update set
  puesto = excluded.puesto,
  puntos = excluded.puntos,
  anio = excluded.anio,
  calificacion = excluded.calificacion,
  calificacion_origen = excluded.calificacion_origen,
  guia = excluded.guia,
  evento_id = excluded.evento_id,
  validado = 'validado';

on conflict (id) do update set
  puesto = excluded.puesto,
  puntos = excluded.puntos,
  anio = excluded.anio,
  calificacion = excluded.calificacion,
  calificacion_origen = excluded.calificacion_origen,
  guia = excluded.guia,
  evento_id = excluded.evento_id,
  validado = 'validado';

alter table resultados enable trigger trg_proteger_resultado;

commit;

-- 3. Comprobación: deben salir 5 campeonatos, 197 participaciones
--    y 110 ejemplares.
select (select count(*) from eventos where tipo = 'trabajo') as campeonatos,
       (select count(*) from resultados where tipo_evento = 'IGP') as participaciones,
       (select count(distinct perro_id) from resultados where tipo_evento = 'IGP') as ejemplares,
       (select count(*) from resultados where tipo_evento = 'IGP' and validado <> 'validado') as sin_validar;
